(7219272, 1112589, 67697, '<td valign="top">Congrats on moving forward in the next round of the beat your own average challenege.  Good luck!</td>', 'Congrats on moving forward in the next round of the beat your own average challenege.  Good luck!', '2014-05-21 13:53:29.000000', NULL, 0),
