(7219531, 1112515, 101668, '<td valign="top">Great stuff Wendy, and natural non posed and very difficult. It certainly deserves the blue. Congrats</td>', 'Great stuff Wendy, and natural non posed and very difficult. It certainly deserves the blue. Congrats', '2014-05-22 08:26:30.000000', NULL, 0),
