(7219572, 1112595, 140305, '<td valign="top">Great drama in this Alex. Congrats on the ribbon!</td>', 'Great drama in this Alex. Congrats on the ribbon!', '2014-05-22 09:47:23.000000', NULL, 0),
(7219575, 1112450, 140305, '<td valign="top">My husband and I visited this ship a couple of years ago (along with the Arizona memorial). Powerfully moving reminders of those days. You did this great ship proud. Congrats on the ribbon!</td>', 'My husband and I visited this ship a couple of years ago (along with the Arizona memorial). Powerfully moving reminders of those days. You did this great ship proud. Congrats on the ribbon!', '2014-05-22 09:52:46.000000', NULL, 0),
